if (window.innerWidth < TOC_MIN_WIDTH) return;
const proseEl = document.getElementById('proseZh')
|| document.querySelector('article.prose')
|| document.querySelector('article .prose')
|| document.querySelector('article.max-w-3xl');
if (!proseEl) return;
var allH2 = proseEl.querySelectorAll('h2');
